using namespace std;
inline void rd(){}
template<typename T,typename ...U>
inline void rd(T &x,U &...args){
	char ch=getchar();
	T f=1;x=0;
    while(ch<'0'||ch>'9'){if(ch=='-')f=-1;ch=getchar();}
    while(ch>='0'&&ch<='9')x=(x<<1)+(x<<3)+(ch^48),ch=getchar();
	x*=f;rd(args...);
}
typedef long long ll;
const int N=2e5+5,V=1e6+5;
int T,n,a[N];ll r[V];
inline void Solve(){
	memset(r,-0x3f,sizeof r);
	ll mxr=0,tgr=0;rd(n);
	for(int i=1;i<=n;i++){
		rd(a[i]);
		ll tmpr=max(mxr,r[a[i]]+a[i])+tgr;
		if(a[i]==a[i-1])tgr+=a[i];
		r[a[i-1]]=max(r[a[i-1]],tmpr-tgr);
		mxr=max(mxr,r[a[i-1]]);
	}
	mxr=0;
	for(int i=1;i<=1000000;i++)mxr=max(mxr,r[i]);
	printf("%lld\n",mxr+tgr);
}
signed main(){
	rd(T);
	while(T--)Solve();
	return 0;
}

#include <bits/stdc++.h>
#define int long long

using namespace std;

int n, t[1000001], suf[200001], f[200001]; vector<int > a;

void solve() {
	cin >> n; a.clear(); a.push_back(0);
	memset(t, 0, sizeof(t));
	memset(suf, 0, sizeof(suf));
	memset(f, 0, sizeof(f));
	int ans = 0;
	for (int i = 1, v; i <= n; i++) {
		cin >> v;
		if (!a.size() || v != a.back())
			a.push_back(v);
		else
			ans += v;
	} n = a.size() - 1;
	for (int i = 1; i <= n; t[a[i]] = i, i++)
		if (t[a[i]])
			suf[t[a[i]]] = i; 
	for (int i = n; i; i--)
		if (suf[i])
			f[i] = max(f[i + 1], f[suf[i] - 1] + a[i]);
		else
			f[i] = f[i + 1];
	cout << ans + f[1] << '\n';
}

signed main() {
	cin.tie(0)->sync_with_stdio(false);


	int t; cin >> t;
	while (t--) solve();
	return 0;
}
